// === Tab: mySketch ===
// reference: https://twitter.com/ryotakob/status/1572582640611643394

function setup() {
	createCanvas(720,720)
	noStroke()
	colorMode(HSB, 9)
	background(0)
	noLoop()
}

function draw() {
	for (let k = 0; k < 80; k++) {
    push()
		fill([3, 5, 8][k % 3], 4, 9)
    scale(sin(k))
    translate(1e3 * sin(k ** 3), 1e3 * sin(k ** 7));
		for (let j = 0; j < 12; j++) {
			rotate(.52)
			for (let i =0; i < 205 + int(25 * sin(j * k)); i++) {
				circle(i, 0, min(sq(i - 160) / 99 + 9, 99))
			}
		}
		pop()
  }
}

function keyPressed() {
	redraw();
}

